import numpy as np
from scipy.optimize import minimize

class HybridGA:
    def __init__(self, budget=10000, dim=10, population_size=20, mutation_rate=0.1, crossover_rate=0.7, local_search_rate=0.2):
        self.budget = budget
        self.dim = dim
        self.population_size = population_size
        self.mutation_rate = mutation_rate
        self.crossover_rate = crossover_rate
        self.local_search_rate = local_search_rate
        self.lb = -5.0
        self.ub = 5.0
        self.mutation_step = 0.5  # Initial mutation step size
        self.mutation_step_decay = 0.99  # Decay factor for mutation step
        self.rng = np.random.default_rng()

    def initialize_population(self):
        return self.rng.uniform(self.lb, self.ub, size=(self.population_size, self.dim))

    def evaluate_population(self, func, population):
        fitness = np.array([func(x) for x in population])
        return fitness

    def select_parents(self, population, fitness):
        # Tournament selection
        parents = []
        for _ in range(self.population_size):
            indices = self.rng.choice(len(population), size=2, replace=False)
            if fitness[indices[0]] < fitness[indices[1]]:
                parents.append(population[indices[0]])
            else:
                parents.append(population[indices[1]])
        return np.array(parents)

    def crossover(self, parents):
        offspring = []
        for i in range(0, len(parents), 2):
            if self.rng.random() < self.crossover_rate and i + 1 < len(parents):
                crossover_point = self.rng.integers(1, self.dim)
                offspring1 = np.concatenate((parents[i][:crossover_point], parents[i+1][crossover_point:]))
                offspring2 = np.concatenate((parents[i+1][:crossover_point], parents[i][crossover_point:]))
                offspring.extend([offspring1, offspring2])
            else:
                offspring.append(parents[i])
                if i + 1 < len(parents):
                    offspring.append(parents[i+1])
        return np.array(offspring)

    def mutate(self, offspring):
        for i in range(len(offspring)):
            if self.rng.random() < self.mutation_rate:
                offspring[i] += self.rng.normal(0, self.mutation_step, size=self.dim)
                offspring[i] = np.clip(offspring[i], self.lb, self.ub)  # Clip to bounds
        return offspring

    def local_search(self, func, individual):
        # Use a simple local search (e.g., L-BFGS-B from scipy)
        result = minimize(func, individual, method='L-BFGS-B', bounds=[(self.lb, self.ub)] * self.dim)
        return result.x, result.fun

    def __call__(self, func):
        population = self.initialize_population()
        fitness = self.evaluate_population(func, population)
        self.f_opt = np.min(fitness)
        self.x_opt = population[np.argmin(fitness)]
        evaluations_used = self.population_size

        while evaluations_used < self.budget:
            # Selection, Crossover, Mutation
            parents = self.select_parents(population, fitness)
            offspring = self.crossover(parents)
            offspring = self.mutate(offspring)
            # Local Search Application
            for i in range(len(offspring)):
                if self.rng.random() < self.local_search_rate and evaluations_used + 5 < self.budget:  # Use local search sparingly
                    offspring[i], f_local = self.local_search(func, offspring[i])
                    if f_local < self.f_opt:
                        self.f_opt = f_local
                        self.x_opt = offspring[i]

            # Evaluate offspring
            fitness_offspring = self.evaluate_population(func, offspring)
            evaluations_used += len(offspring)
            # Replace worst individuals
            for i in range(len(offspring)):
                if fitness_offspring[i] < fitness[np.argmax(fitness)]:
                    fitness[np.argmax(fitness)] = fitness_offspring[i]
                    population[np.argmax(fitness)] = offspring[i]

            if evaluations_used % (self.budget // 10) == 0:
                self.mutation_step *= self.mutation_step_decay # Adapt mutation step


        return self.f_opt, self.x_opt
